#!/usr/bin/env bash
# recipes/crate-wasm-bindgen-futures--0-4-40/build.sh -- stage the wasm-bindgen-futures 0.4.40 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/wasm-bindgen-futures-0.4.40"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"bde2032aeb86bdfaecc8b261eef3cba735cc426c1f3a3416d1e0791be95fc461"}\n' > "${dest}/.cargo-checksum.json"
